# Homebrew formula for demodsl — generated by .github/workflows/publish.yml.
#
# Install with:  brew install Fran-cois/demodsl/demodsl
#
# This formula ships the standalone PyInstaller binaries attached to each
# GitHub Release rather than building a Python virtualenv from source.
# A source build would need a `resource` stanza for every transitive
# dependency (playwright, pydantic, typer, ...), regenerated on every
# release. The release binaries are already built and smoke-tested by CI,
# so this stays correct on its own.
#
# The __PLACEHOLDER__ values are substituted by CI from the real assets.

class Demodsl < Formula
  desc "DSL-driven automated product demo video generator"
  homepage "https://fran-cois.github.io/demodsl"
  version "3.13.2"
  license "MIT"

  depends_on "ffmpeg"

  on_macos do
    on_arm do
      url "https://github.com/Fran-cois/demodsl/releases/download/v3.13.2/demodsl-3.13.2-macos-aarch64.tar.gz"
      sha256 "ade0254be0e1774d2fa9d1774c11a89b4a93c66b018c6891d1e26fb257b44d6c"
    end
    on_intel do
      url "https://github.com/Fran-cois/demodsl/releases/download/v3.13.2/demodsl-3.13.2-macos-x86_64.tar.gz"
      sha256 "0bea51d0da1fe42c3df01fdec75632c6fd6c707abca7959d766efbbb998ff8cc"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/Fran-cois/demodsl/releases/download/v3.13.2/demodsl-3.13.2-linux-x86_64.tar.gz"
      sha256 "2839aa4893d5130298a7b8efa0cc3b91ebf5550dadb7196c8c2a8756a3377eac"
    end
  end

  def install
    bin.install "demodsl"
  end

  def caveats
    <<~EOS
      Rendering a demo drives a real browser, and the standalone binary does
      not ship Playwright's Chromium. Commands that never touch a browser
      (validate, capabilities, estimate, qa, eval) work as-is.

      To record a page, install the browser once:
        pipx run playwright install chromium

      ffmpeg is pulled in as a dependency and is used for the final encode.
    EOS
  end

  test do
    assert_match "Usage", shell_output("#{bin}/demodsl --help")
    assert_match version.to_s, shell_output("#{bin}/demodsl capabilities")
  end
end
